      if (Object.prototype.hasOwnProperty.call(primary, key)) return primary[key];
      const other = lang === 'en' ? WEATHER_DICT.zh : WEATHER_DICT.en;
      if (Object.prototype.hasOwnProperty.call(other, key)) return other[key];
      return key;
